/* ---------- Modals ---------- */
var activeOverlay=null,lastFocus=null;
var FOCUSABLE='a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea,[tabindex]:not([tabindex="-1"])';
function openModal(ov){
  lastFocus=document.activeElement;activeOverlay=ov;
  ov.classList.add('show');ov.setAttribute('aria-hidden','false');document.body.classList.add('locked');
  requestAnimationFrame(function(){ov.classList.add('vis');
    var f=$$(FOCUSABLE,ov).filter(function(x){return x.offsetParent!==null&&!x.classList.contains('close')});
    (f[0]||$('.modal',ov)).focus();
  });
}
function closeModal(){
  var ov=activeOverlay;if(!ov)return;
  ov.classList.remove('vis');ov.setAttribute('aria-hidden','true');activeOverlay=null;
  setTimeout(function(){ov.classList.remove('show')},300);
  document.body.classList.remove('locked');
  if(lastFocus&&lastFocus.focus)lastFocus.focus();
}
$$('.overlay').forEach(function(ov){
  ov.addEventListener('mousedown',function(e){if(e.target===ov)closeModal()});
  $$('[data-close]',ov).forEach(function(b){b.addEventListener('click',closeModal)});
});
document.addEventListener('keydown',function(e){
  if(!activeOverlay)return;
  if(e.key==='Escape'){e.preventDefault();closeModal();return}
  if(e.key==='Tab'){
    var f=$$(FOCUSABLE,activeOverlay).filter(function(x){return x.offsetParent!==null});
    if(!f.length)return;var first=f[0],last=f[f.length-1];
    if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.modal',activeOverlay))){e.preventDefault();last.focus()}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
  }
});

