/* ticket modal */
var qty=1,form=$('#ticketForm'),tkTier=$('#tkTier');
function tier(){return tiers.filter(function(t){return t.id===tkTier.value})[0]}
function updTotal(){$('#qVal').textContent=qty;$('#tkTotal').textContent='€'+(tier().price*qty)}
function setErr(input,errEl,msg){errEl.textContent=msg||'';if(input){if(msg)input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid')}}
var emailRe=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
$('#qMinus').addEventListener('click',function(){if(qty>1){qty--;updTotal()}});
$('#qPlus').addEventListener('click',function(){if(qty<10){qty++;updTotal()}else toast('Maximum 10 tickets per reservation.','error')});
tkTier.addEventListener('change',updTotal);
$('#tiers').addEventListener('click',function(e){
  var b=e.target.closest('[data-tier]');if(!b)return;
  form.reset();qty=1;tkTier.value=b.dataset.tier;updTotal();
  ['#tkName','#tkEmail'].forEach(function(s){$(s).removeAttribute('aria-invalid')});
  ['#tkNameErr','#tkEmailErr','#tkTermsErr'].forEach(function(s){$(s).textContent=''});
  form.classList.remove('hidden');$('#tkSuccess').classList.add('hidden');
  openModal($('#ticketOverlay'));
});
form.addEventListener('submit',function(e){
  e.preventDefault();
  var n=$('#tkName'),m=$('#tkEmail'),t=$('#tkTerms'),bad=null;
  var nv=n.value.trim(),mv=m.value.trim();
  setErr(n,$('#tkNameErr'),nv.length<2?'Please enter the attendee name.':'');
  setErr(m,$('#tkEmailErr'),!mv?'Please enter your email.':(!emailRe.test(mv)?'Please enter a valid email address.':''));
  setErr(null,$('#tkTermsErr'),t.checked?'':'Please accept the terms to continue.');
  if(nv.length<2)bad=n;else if(!emailRe.test(mv))bad=m;else if(!t.checked)bad=t;
  if(bad){bad.focus();toast('Please fix the highlighted fields.','error');return}
  var tr=tier();
  $('#tkSummary').textContent=qty+' × '+tr.name+' reserved for '+nv+' — total €'+(tr.price*qty)+'. A confirmation would be sent to '+mv+'. (Demo — no payment taken.)';
  form.classList.add('hidden');var s=$('#tkSuccess');s.classList.remove('hidden');s.focus();
  toast('Reservation confirmed — see you after dark!');
});
['#tkName','#tkEmail'].forEach(function(s){$(s).addEventListener('input',function(){this.removeAttribute('aria-invalid');$(s+'Err').textContent=''})});
