/* ---------- ICS ---------- */
function icsEsc(s){return s.replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\n/g,'\\n')}
function downloadICS(){
  var d=new Date(),p=function(n){return String(n).padStart(2,'0')};
  var stamp=d.getUTCFullYear()+p(d.getUTCMonth()+1)+p(d.getUTCDate())+'T'+p(d.getUTCHours())+p(d.getUTCMinutes())+p(d.getUTCSeconds())+'Z';
  var lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ARTIFACT//Museum Night//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH',
   'BEGIN:VEVENT','UID:artifact-museum-night-20261018@artifact.example','DTSTAMP:'+stamp,
   'DTSTART:20261018T190000','DTEND:20261019T020000',
   'SUMMARY:'+icsEsc('ARTIFACT: Museum Night'),'LOCATION:'+icsEsc('The Old Gallery, Warsaw'),
   'DESCRIPTION:'+icsEsc('A cinematic after-hours museum event with exhibitions, performances, talks, and guided tours.'),
   'END:VEVENT','END:VCALENDAR'];
  var blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'});
  var url=URL.createObjectURL(blob),a=document.createElement('a');
  a.href=url;a.download='artifact-museum-night.ics';a.style.display='none';
  document.body.appendChild(a);a.click();
  setTimeout(function(){document.body.removeChild(a);URL.revokeObjectURL(url)},1000);
  toast('Calendar file downloaded.');
}
$$('[data-ics]').forEach(function(b){b.addEventListener('click',downloadICS)});
})();
